function normalizeQuery(query) {
	return query.trim().replace(/\s+/g, " ").slice(0, 600);
}
function isChatQueryInScope(query, contextQuery = "") {
	const normalized = normalizeQuery(query);
	const context = normalizeQuery(contextQuery);
	if (!normalized || PRIVATE_PATTERNS.some((pattern) => pattern.test(normalized))) return false;
	if (context && PRIVATE_PATTERNS.some((pattern) => pattern.test(context))) return false;
	if (HARD_UNRELATED_PATTERNS.some((pattern) => pattern.test(normalized))) return false;
	const hasPortfolioSignal = PORTFOLIO_SIGNAL_PATTERNS.some((pattern) => pattern.test(normalized));
	const hasDesignContext = DESIGN_CONTEXT_PATTERNS.some((pattern) => pattern.test(normalized));
	if (SOFT_UNRELATED_PATTERNS.some((pattern) => pattern.test(normalized)) && !hasPortfolioSignal && !hasDesignContext) return false;
	if (hasPortfolioSignal || hasDesignContext) return true;
	if (GENERIC_PERSON_REQUEST.test(normalized) || GENERIC_SCOPE_REQUEST.test(normalized) || GENERIC_CAPABILITY_REQUEST.test(normalized)) return true;
	return Boolean(context && CONTEXTUAL_FOLLOW_UP.test(normalized) && !HARD_UNRELATED_PATTERNS.some((pattern) => pattern.test(normalized)) && !SOFT_UNRELATED_PATTERNS.some((pattern) => pattern.test(normalized)) && (PORTFOLIO_SIGNAL_PATTERNS.some((pattern) => pattern.test(context)) || DESIGN_CONTEXT_PATTERNS.some((pattern) => pattern.test(context))));
}
function findChatKnowledge(query, limit = 5) {
	const normalized = normalizeQuery(query).toLowerCase();
	if (!normalized) return [];
	const ranked = chatKnowledge.map((entry, index) => {
		let score = [...new Set([...entry.keywords, ...KNOWLEDGE_ALIASES[entry.id] ?? []])].reduce((total, keyword) => {
			const normalizedKeyword = keyword.toLowerCase();
			if (!normalizedKeyword || !normalized.includes(normalizedKeyword)) return total;
			return total + (normalizedKeyword.length >= 5 ? 6 : normalizedKeyword.length >= 3 ? 4 : 2);
		}, 0);
		if (normalized.includes(entry.title.toLowerCase())) score += 8;
		for (const hint of TOPIC_HINTS) if (hint.pattern.test(normalized) && hint.ids.includes(entry.id)) score += hint.weight;
		if (GENERIC_OVERVIEW_PATTERN.test(normalized) && !SPECIFIC_PROJECT_PATTERN.test(normalized) && [
			"project-overview",
			"experience-overview",
			"capability-overview"
		].includes(entry.id)) score += 9;
		if (entry.id === "assistant-scope" && !/能回答|可以问|能聊|范围|帮助|公开内容/i.test(normalized)) score *= .55;
		return {
			entry,
			score,
			index
		};
	}).filter((item) => item.score > 0).sort((left, right) => right.score - left.score || left.index - right.index).slice(0, limit).map((item) => item.entry);
	if (ranked.length) return ranked;
	const fallbackIds = [];
	for (const hint of TOPIC_HINTS) {
		if (!hint.pattern.test(normalized)) continue;
		for (const id of hint.ids) if (!fallbackIds.includes(id)) fallbackIds.push(id);
	}
	if (GENERIC_PERSON_REQUEST.test(normalized) || GENERIC_SCOPE_REQUEST.test(normalized) || GENERIC_CAPABILITY_REQUEST.test(normalized)) {
		const ids = /能回答|可以问|能聊|范围|帮助|做什么|提供什么/i.test(normalized) ? [
			"assistant-scope",
			"capability-overview",
			"profile",
			"experience-overview"
		] : [
			"profile",
			"capability-overview",
			"experience-overview",
			"assistant-scope"
		];
		for (const id of ids) if (!fallbackIds.includes(id)) fallbackIds.push(id);
	}
	if (!fallbackIds.length) fallbackIds.push("assistant-scope", "profile", "capability-overview");
	return fallbackIds.map((id) => chatKnowledge.find((entry) => entry.id === id)).filter((entry) => Boolean(entry)).slice(0, limit);
}
function buildLocalChatReply(query, contextQuery = query) {
	if (!isChatQueryInScope(query, contextQuery)) return {
		reply: OUT_OF_SCOPE_REPLY,
		entries: []
	};
	const entries = findChatKnowledge(`${query} ${contextQuery}`);
	if (!entries.length) return {
		reply: OUT_OF_SCOPE_REPLY,
		entries: []
	};
	return {
		reply: entries.slice(0, 2).map((entry) => entry.content).join("\n\n"),
		entries
	};
}
